// frontend/src/App.js
// Setup: npx create-react-app frontend
// cd frontend
// npm install axios
// npm start (runs on localhost:3000)
// Backend should be running on localhost:8000

import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './App.css';

function App() {
  const [cities, setCities] = useState([]);
  const [weatherData, setWeatherData] = useState({});
  const [newCity, setNewCity] = useState('');
  const [error, setError] = useState('');

  const fetchWeather = async (city) => {
    try {
      const response = await axios.get(`http://localhost:8000/weather?city=${city}`);
      return { [city.toLowerCase()]: response.data };
    } catch (err) {
      console.error(`Error fetching weather for ${city}:`, err);
      return null;
    }
  };

  const updateAllWeather = async () => {
    const promises = cities.map(city => fetchWeather(city));
    const results = await Promise.all(promises);
    const newData = results.reduce((acc, curr) => ({ ...acc, ...curr }), {});
    setWeatherData(prev => ({ ...prev, ...newData }));
  };

  useEffect(() => {
    if (cities.length > 0) {
      updateAllWeather();
      const interval = setInterval(updateAllWeather, 60000); // Every minute
      return () => clearInterval(interval);
    }
  }, [cities]);

  const addCity = () => {
    if (!newCity.trim()) return;
    const normalized = newCity.trim().toLowerCase();
    if (!cities.some(c => c.toLowerCase() === normalized)) {
      setCities(prev => [...prev, newCity.trim()]);
      setError('');
    } else {
      setError('City already added');
    }
    setNewCity('');
  };

  const removeCity = (city) => {
    setCities(prev => prev.filter(c => c.toLowerCase() !== city.toLowerCase()));
    setWeatherData(prev => {
      const { [city.toLowerCase()]: _, ...rest } = prev;
      return rest;
    });
  };

  return (
    <div className="App">
      <h1>Real-Time Weather Dashboard</h1>
      <div className="add-city">
        <input
          type="text"
          value={newCity}
          onChange={(e) => setNewCity(e.target.value)}
          placeholder="Enter city name"
        />
        <button onClick={addCity}>Add City</button>
        {error && <p className="error">{error}</p>}
      </div>
      <div className="dashboard">
        {cities.map(city => {
          const data = weatherData[city.toLowerCase()];
          return (
            <div key={city} className="weather-card">
              <h2>{city}</h2>
              {data ? (
                <>
                  <p>Temperature: {data.temperature} °C</p>
                  <p>Humidity: {data.humidity}%</p>
                  <p>Condition: {data.condition}</p>
                </>
              ) : (
                <p>Loading...</p>
              )}
              <button onClick={() => removeCity(city)}>Remove</button>
            </div>
          );
        })}
      </div>
    </div>
  );
}

export default App;
